This React 18 component is under `ConvexProvider` using Convex 1.44.0. `api.messages.sendMessage` references a public mutation that inserts its `author` and `body` arguments.

```ts
import React, { useState } from "react";
import { useMutation } from "convex/react";
import { api } from "../convex/_generated/api";
export function Send() {
  BINDING
  const [sending, setSending] = useState(false);
  async function submit() {
    setSending(true);
    try {
      await send({ author: "Ada", body: "Hello" });
    } finally {
      setSending(false);
    }
  }
  return <button onClick={submit}>{sending ? "Sending..." : "Send"}</button>;
}
